import * as childProcess from 'child_process';
import fs from 'fs';
import path from 'path';
import { z } from 'zod';
import { uninstallHarnesses } from './harnesses';
import { subprocessEnvironment } from '../utils/subprocessEnvironment';
import { writeFileAtomicSync } from '../utils/writeFileAtomic';
import { errorMessage } from '../utils/errorMessage';
import {
  describeProcessCommand,
  spawnProcessSync,
  type ProcessCommand,
} from '../services/packageManagerProcess';

const RivetChannelSchema = z.enum(['local', 'production']);
export type RivetChannel = z.infer<typeof RivetChannelSchema>;

const ChannelStateSchema = z.object({
  schemaVersion: z.literal(1),
  channel: RivetChannelSchema,
  targetBin: z.string().min(1),
});

type ChannelState = z.infer<typeof ChannelStateSchema>;

type ChannelCommandOptions = {
  cwd?: string;
  env?: NodeJS.ProcessEnv;
};

export type ChannelCommandRunner = (
  command: ProcessCommand,
  options: ChannelCommandOptions,
) => void;

export type ChannelHostUninstaller = (hosts: string[]) => { exitCode: number };

type RivetChannelsOptions = {
  commandRunner?: ChannelCommandRunner;
  globalPrefix: string;
  homeDirectory: string;
  hostUninstaller?: ChannelHostUninstaller;
  nodePath?: string;
  repoRoot: string;
  revisionReader?: () => string | undefined;
};

type ChannelDetails = {
  binPath: string;
  isAvailable: boolean;
  revision?: string;
  version?: string;
};

export type RivetChannelStatus = {
  activeChannel: RivetChannel | null;
  activeCliPath: string;
  isCliInstalled: boolean;
  local: ChannelDetails;
  production: ChannelDetails;
  selectedChannel: RivetChannel | null;
};

const DEFAULT_COMMAND_ENV = { CI: 'true' } as const;
const PRODUCTION_PACKAGE_SPEC = 'rivet-design@latest';
const STATE_SCHEMA_VERSION = 1 as const;
const OWNER_ONLY_FILE_MODE = 0o600;

const runCommand: ChannelCommandRunner = (command, options): void => {
  const result = spawnProcessSync(command, {
    cwd: options.cwd,
    env: options.env,
    stdio: 'inherit',
  });
  const name = describeProcessCommand(command);
  if (result.error) {
    throw new Error(`Could not run ${name}: ${result.error.message}`);
  }
  if (result.status !== 0) {
    throw new Error(`${name} exited with status ${String(result.status)}`);
  }
};

const pathExists = (filePath: string): boolean => {
  try {
    fs.lstatSync(filePath);
    return true;
  } catch {
    return false;
  }
};

const readSymlinkTarget = (linkPath: string): string =>
  path.resolve(path.dirname(linkPath), fs.readlinkSync(linkPath));

const pathIdentities = (filePath: string): Set<string> => {
  const identities = new Set([path.normalize(path.resolve(filePath))]);
  try {
    identities.add(path.normalize(fs.realpathSync(filePath)));
  } catch {}
  return identities;
};

const pathsIdentifySameTarget = (left: string, right: string): boolean => {
  const rightIdentities = pathIdentities(right);
  return [...pathIdentities(left)].some((identity) =>
    rightIdentities.has(identity),
  );
};

const versionForBin = (binPath: string): string | undefined => {
  try {
    const packagePath = path.join(path.dirname(binPath), '..', 'package.json');
    const parsed = JSON.parse(fs.readFileSync(packagePath, 'utf8')) as {
      version?: unknown;
    };
    return typeof parsed.version === 'string' ? parsed.version : undefined;
  } catch {
    return undefined;
  }
};

const readRevision = (repoRoot: string): string | undefined => {
  const result = childProcess.spawnSync(
    'git',
    ['-C', repoRoot, 'rev-parse', '--short', 'HEAD'],
    { encoding: 'utf8', env: subprocessEnvironment('git') },
  );
  return result.status === 0 ? result.stdout.trim() : undefined;
};

export class RivetChannels {
  private readonly activeCliPath: string;
  private readonly channelRoot: string;
  private readonly commandRunner: ChannelCommandRunner;
  private readonly globalPrefix: string;
  private readonly homeDirectory: string;
  private readonly hostUninstaller: ChannelHostUninstaller;
  private readonly localBinPath: string;
  private readonly nodePath: string;
  private readonly productionBinPath: string;
  private readonly productionPrefix: string;
  private readonly repoRoot: string;
  private readonly revisionReader: () => string | undefined;
  private readonly statePath: string;

  public constructor(options: RivetChannelsOptions) {
    this.commandRunner = options.commandRunner ?? runCommand;
    this.globalPrefix = options.globalPrefix;
    this.homeDirectory = options.homeDirectory;
    this.hostUninstaller = options.hostUninstaller ?? uninstallHarnesses;
    this.nodePath = options.nodePath ?? process.execPath;
    this.repoRoot = options.repoRoot;
    this.revisionReader =
      options.revisionReader ?? (() => readRevision(this.repoRoot));
    this.channelRoot = path.join(this.homeDirectory, '.rivet', 'channels');
    this.productionPrefix = path.join(this.channelRoot, 'production');
    this.localBinPath = path.join(this.repoRoot, 'bin', 'rivet.js');
    this.productionBinPath = path.join(
      this.productionPrefix,
      'node_modules',
      'rivet-design',
      'bin',
      'rivet.js',
    );
    this.statePath = path.join(this.channelRoot, 'active.json');
    this.activeCliPath = path.join(this.globalPrefix, 'bin', 'rivet');
  }

  public refresh(channel: RivetChannel): void {
    if (channel === 'local') {
      this.commandRunner(
        { packageManager: 'yarn', args: ['build'] },
        { cwd: this.repoRoot, env: subprocessEnvironment('packageManager') },
      );
      this.requireTarget(channel);
      return;
    }

    fs.mkdirSync(this.productionPrefix, { recursive: true });
    this.commandRunner(
      {
        packageManager: 'npm',
        args: [
          'install',
          '--prefix',
          this.productionPrefix,
          '--no-audit',
          '--no-fund',
          '--no-package-lock',
          PRODUCTION_PACKAGE_SPEC,
        ],
      },
      { env: subprocessEnvironment('packageManager') },
    );
    this.requireTarget(channel);
  }

  public install(channel: RivetChannel, hosts: string[]): void {
    this.refresh(channel);
    this.use(channel, hosts);
  }

  public use(channel: RivetChannel, hosts: string[]): void {
    const targetBin = this.requireTarget(channel);
    this.activateCli({ channel, targetBin });
    this.commandRunner(
      {
        executable: this.nodePath,
        args: [targetBin, 'install', ...hosts, '--no-telemetry'],
      },
      {
        env: {
          ...subprocessEnvironment('rivetRuntime'),
          ...DEFAULT_COMMAND_ENV,
        },
      },
    );
  }

  public uninstall(hosts: string[], isCliRemovalRequested: boolean): void {
    if (isCliRemovalRequested && (hosts.length !== 1 || hosts[0] !== 'all')) {
      throw new Error('--remove-cli requires the all target');
    }
    const result = this.hostUninstaller(hosts);
    if (result.exitCode !== 0) {
      throw new Error('Could not uninstall Rivet from every requested host');
    }
    if (isCliRemovalRequested) {
      this.removeActiveCli();
    }
  }

  public status(): RivetChannelStatus {
    const state = this.readState();
    const isCliInstalled = this.isActiveCli(state);
    return {
      activeChannel: isCliInstalled ? (state?.channel ?? null) : null,
      activeCliPath: this.activeCliPath,
      isCliInstalled,
      local: {
        binPath: this.localBinPath,
        isAvailable: fs.existsSync(this.localBinPath),
        revision: this.revisionReader(),
        version: versionForBin(this.localBinPath),
      },
      production: {
        binPath: this.productionBinPath,
        isAvailable: fs.existsSync(this.productionBinPath),
        version: versionForBin(this.productionBinPath),
      },
      selectedChannel: state?.channel ?? null,
    };
  }

  private requireTarget(channel: RivetChannel): string {
    const targetBin =
      channel === 'local' ? this.localBinPath : this.productionBinPath;
    if (!fs.existsSync(targetBin)) {
      throw new Error(
        `${channel} Rivet is unavailable at ${targetBin}; run install or refresh first`,
      );
    }
    return targetBin;
  }

  private activateCli(state: Omit<ChannelState, 'schemaVersion'>): void {
    fs.mkdirSync(path.dirname(this.activeCliPath), { recursive: true });
    if (pathExists(this.activeCliPath)) {
      const stats = fs.lstatSync(this.activeCliPath);
      if (!stats.isSymbolicLink()) {
        throw new Error(
          `Refusing to replace unmanaged Rivet CLI at ${this.activeCliPath}`,
        );
      }
      const currentTarget = readSymlinkTarget(this.activeCliPath);
      if (!this.isManagedTarget(currentTarget)) {
        throw new Error(
          `Refusing to replace unmanaged Rivet CLI at ${this.activeCliPath}`,
        );
      }
      fs.unlinkSync(this.activeCliPath);
    }
    fs.symlinkSync(state.targetBin, this.activeCliPath);
    this.writeState(state);
  }

  private isManagedTarget(targetPath: string): boolean {
    const state = this.readState();
    const packageSuffix = path.join(
      'node_modules',
      'rivet-design',
      'bin',
      'rivet.js',
    );
    return (
      pathsIdentifySameTarget(targetPath, this.localBinPath) ||
      pathsIdentifySameTarget(targetPath, this.productionBinPath) ||
      (state !== undefined &&
        pathsIdentifySameTarget(targetPath, state.targetBin)) ||
      [...pathIdentities(targetPath)].some((identity) =>
        identity.endsWith(packageSuffix),
      )
    );
  }

  private removeActiveCli(): void {
    const state = this.readState();
    if (!pathExists(this.activeCliPath)) return;
    if (!state || !this.isActiveCli(state)) {
      throw new Error(
        `Refusing to remove unmanaged Rivet CLI at ${this.activeCliPath}`,
      );
    }
    fs.unlinkSync(this.activeCliPath);
  }

  private isActiveCli(state: ChannelState | undefined): boolean {
    if (!state || !pathExists(this.activeCliPath)) return false;
    try {
      return (
        fs.lstatSync(this.activeCliPath).isSymbolicLink() &&
        pathsIdentifySameTarget(
          readSymlinkTarget(this.activeCliPath),
          state.targetBin,
        )
      );
    } catch {
      return false;
    }
  }

  private readState(): ChannelState | undefined {
    if (!fs.existsSync(this.statePath)) return undefined;
    try {
      return ChannelStateSchema.parse(
        JSON.parse(fs.readFileSync(this.statePath, 'utf8')),
      );
    } catch (error) {
      throw new Error(
        `Invalid Rivet channel state at ${this.statePath}: ${errorMessage(error)}`,
      );
    }
  }

  private writeState(state: Omit<ChannelState, 'schemaVersion'>): void {
    fs.mkdirSync(path.dirname(this.statePath), { recursive: true });
    const nextState: ChannelState = {
      schemaVersion: STATE_SCHEMA_VERSION,
      ...state,
    };
    writeFileAtomicSync(
      this.statePath,
      `${JSON.stringify(nextState, null, 2)}\n`,
      { mode: OWNER_ONLY_FILE_MODE },
    );
  }
}

export const parseRivetChannel = (value: string | undefined): RivetChannel => {
  const parsed = RivetChannelSchema.safeParse(value);
  if (!parsed.success) {
    throw new Error('Channel must be local or production');
  }
  return parsed.data;
};
